class PrivateLotStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = [self.AddEquity(ticker, Resolution.Daily).Symbol for ticker in tickers]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.closes = {symbol: RollingWindow[float](101) for symbol in self.symbols}
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        for symbol in self.symbols:
            if symbol in data.Bars:
                self.closes[symbol].Add(float(data.Bars[symbol].Close))

        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        spy_closes = self.closes[self.spy]
        aapl_closes = self.closes[self.aapl]

        if spy_closes.Count < 101 or aapl_closes.Count < 4 or not self.aapl_rsi.IsReady:
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        spy_sma_today = sum(spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(spy_closes[i] for i in range(1, 101)) / 100.0
        spy_crosses_above = spy_closes[1] <= spy_sma_yesterday and spy_close > spy_sma_today
        spy_crosses_below = spy_closes[1] >= spy_sma_yesterday and spy_close < spy_sma_today

        aapl_three_red_days = (
            aapl_closes[0] < aapl_closes[1]
            and aapl_closes[1] < aapl_closes[2]
            and aapl_closes[2] < aapl_closes[3]
        )

        # Sells are evaluated before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            shares = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) / spy_close)
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and aapl_three_red_days:
            if float(self.Portfolio.Cash) >= 20_000:
                shares = int(20_000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_lot = shares
